def enhance_openevolve_code(
    code: str,
    tests: List[Dict[str, Any]] = None,
    problem_description: str = "",
    language: str = None,
    max_iterations: int = 5,
) -> EnhancementResult:
    """
    Convenience function to enhance OpenEvolve code.
    
    Args:
        code: The code to enhance
        tests: Optional test cases
        problem_description: Description of the problem being solved
        language: Programming language
        max_iterations: Maximum evolution iterations
    
    Returns:
        EnhancementResult with enhanced code
    """
    enhancer = OpenEvolvePESEnhancer(max_iterations=max_iterations)
    return enhancer.enhance(code, problem_description, tests, language)


def quick_enhance(code: str, problem_description: str = "") -> EnhancementResult:
    """
    Quick enhancement with default settings.
    
    Args:
        code: The code to enhance
        problem_description: Description of the problem
    
    Returns:
        EnhancementResult with enhanced code
    """
    return enhance_openevolve_code(code, problem_description=problem_description)


