def enhance_lean_proof(
    lean_code: str,
    theorem_description: str = "",
    max_iterations: int = 3,
) -> Dict[str, Any]:
    """
    Enhance Lean code (theorems/proofs) using the LeanAide PES system.
    
    This function specifically handles Lean 4 code and can:
    - Complete incomplete proofs (replace 'sorry' with tactics)
    - Verify theorem structure
    - Suggest appropriate proof tactics
    
    Args:
        lean_code: The Lean code to enhance
        theorem_description: Description of the theorem/problem
        max_iterations: Maximum enhancement iterations
    
    Returns:
        Dict with 'enhanced_code', 'success', 'improvements', 'tests_passed', 'tests_total'
    """
    if not LEANAIDE_PES_AVAILABLE:
        return {
            'enhanced_code': lean_code,
            'success': False,
            'improvements': [],
            'tests_passed': 0,
            'tests_total': 1,
            'error': 'LeanAide PES handler not available'
        }
    
    return lean_enhance_lean_proof(lean_code, theorem_description, max_iterations)


def verify_lean_code(lean_code: str) -> Dict[str, Any]:
    """
    Verify Lean code for common issues.
    
    Args:
        lean_code: Lean code to verify
    
    Returns:
        Dict with 'valid', 'issues', 'has_sorry', 'theorems_found'
    """
    if not LEANAIDE_PES_AVAILABLE:
        return {
            'valid': False,
            'issues': ['LeanAide PES handler not available'],
            'has_sorry': False,
            'theorems_found': 0
        }
    
    return lean_verify_lean_code(lean_code)


def is_lean_code(code: str) -> bool:
    """
    Check if code appears to be Lean 4 code.
    
    Args:
        code: Code to check
    
    Returns:
        True if code appears to be Lean 4
    """
    lean_patterns = [
        r'\btheorem\b',
        r'\blemma\b',
        r'\bdef\b.*:=\b',
        r'\bby\s+(?:simp|trivial|ring|induction)',
        r'\bimport\s+Mathlib',
        r'\bsorry\b',
    ]
    
    for pattern in lean_patterns:
        if __import__('re').search(pattern, code):
            return True
    return False


def detect_language(code: str) -> str:
    """
    Detect the programming language of code.
    
    Args:
        code: Code to analyze
    
    Returns:
        Language string ('python', 'lean', 'javascript', etc.)
    """
    # Check for Lean first
    if is_lean_code(code):
        return 'lean'
    
    # Use the agnostic PES language detector
    if PES_AVAILABLE:
        return LanguageDetector.detect(code)
    
    # Fallback detection
    code_lower = code.lower()
    if 'def ' in code and ':' in code and ' -> ' in code:
        return 'python'
    if 'function' in code and '=>' in code:
        return 'javascript'
    if 'public class' in code:
        return 'java'
    
    return 'unknown'


def enhance_code(
    code: str,
    problem_description: str = "",
    tests: List[Dict[str, Any]] = None,
    language: str = None,
    max_iterations: int = 5,
) -> Dict[str, Any]:
    """
    Universal code enhancement function that handles any language.
    
    This is the main entry point for enhancing code from OpenEvolve.
    It automatically detects the language and uses the appropriate handler.
    
    Args:
        code: The code to enhance
        problem_description: Description of what the code should do
        tests: Optional test cases
        language: Programming language (auto-detected if not provided)
        max_iterations: Maximum enhancement iterations
    
    Returns:
        Dict with 'enhanced_code', 'success', 'language', 'improvements'
    """
    # Auto-detect language if not provided
    if language is None:
        language = detect_language(code)
    
    # Handle Lean code
    if language == 'lean':
        result = enhance_lean_proof(
            lean_code=code,
            theorem_description=problem_description,
            max_iterations=max_iterations
        )
        result['language'] = 'lean'
        return result
    
    # Handle other languages with agnostic PES
    if PES_AVAILABLE:
        enhancement_result = enhance_openevolve_code(
            code=code,
            tests=tests,
            problem_description=problem_description,
            language=language,
            max_iterations=max_iterations
        )
        return {
            'enhanced_code': enhancement_result.enhanced_code,
            'success': enhancement_result.success,
            'language': language,
            'improvements': enhancement_result.improvements,
            'tests_passed': enhancement_result.tests_passed_after,
            'tests_total': enhancement_result.tests_generated,
        }
    
    # Fallback
    return {
        'enhanced_code': code,
        'success': False,
        'language': language,
        'improvements': [],
        'error': 'No enhancement system available'
    }


